#!/usr/bin/env node
/**
 * Public intelligence budget ledger.
 */
import fs from 'node:fs';
import path from 'node:path';

const ROOT = process.cwd();
const OUT = path.join(ROOT, 'api', 'intelligence-budget.json');
const DOC = path.join(ROOT, 'docs', 'INTELLIGENCE_BUDGET_LEDGER.md');
const args = process.argv.slice(2);
const CHECK = args.includes('--check');
const SELF_TEST = args.includes('--self-test');

const SURFACES = [
  { id: 'public-intelligence', file: 'api/public-intelligence.json', posture: 'cached-static', aiCost: 'none-runtime' },
  { id: 'ignis-search-index', file: 'data/ignis-search-index.json', posture: 'local-first', aiCost: 'none-runtime' },
  { id: 'site-health', file: 'api/site-health.json', posture: 'field-rum-aggregate', aiCost: 'none-runtime' },
  { id: 'feedback-provenance', file: 'api/feedback-provenance.json', posture: 'aggregate-public-safe', aiCost: 'none-runtime' },
  { id: 'ux-decision-ledger', file: 'api/ux-decision-ledger.json', posture: 'aggregate-public-safe', aiCost: 'none-runtime' },
  { id: 'nervous-system', file: 'api/nervous-system.json', posture: 'cached-static', aiCost: 'none-runtime' },
  { id: 'ship-receipts', file: 'api/ship-receipts.json', posture: 'aggregate-public-safe', aiCost: 'none-runtime' },
];

function sizeOf(rel) {
  const abs = path.join(ROOT, rel);
  return fs.existsSync(abs) ? fs.statSync(abs).size : 0;
}

export function buildBudget(status = {}) {
  const surfaces = SURFACES.map((surface) => ({
    ...surface,
    bytes: sizeOf(surface.file),
    kb: Number((sizeOf(surface.file) / 1024).toFixed(1)),
    freeTierSafe: surface.aiCost === 'none-runtime',
  }));
  return {
    schemaVersion: '1.0',
    generatedAt: new Date().toISOString(),
    generatedBy: 'scripts/build-intelligence-budget.mjs',
    publicSafe: true,
    freeTierCostStatus: status.freeTierCostStatus || 'AUDIT-PENDING',
    totalBytes: surfaces.reduce((n, s) => n + s.bytes, 0),
    surfaces,
    measurementPlan: [
      'bytes from generated artifact sizes',
      'request count from crawl/browser verification when needed',
      'AI posture from static/local/server-side cost comments and disclosure gates',
    ],
  };
}

function renderDoc(payload) {
  const rows = payload.surfaces.map((s) => `| ${s.id} | ${s.file} | ${s.kb} | ${s.posture} | ${s.aiCost} | ${s.freeTierSafe ? 'yes' : 'no'} |`).join('\n');
  return `<!-- generated-by: scripts/build-intelligence-budget.mjs -->
<!-- generated-at: ${new Date().toISOString().slice(0, 10)} -->

# Intelligence Budget Ledger

Free-tier posture: \`${payload.freeTierCostStatus}\`

| Surface | Artifact | KB | Posture | Runtime AI cost | Free-tier safe |
|---|---|---:|---|---|:-:|
${rows}

Total generated bytes: ${payload.totalBytes}

Measurement plan:
${payload.measurementPlan.map((item) => `- ${item}`).join('\n')}
`;
}

if (SELF_TEST) {
  const payload = buildBudget({ freeTierCostStatus: 'cost-neutral' });
  const cases = [
    ['has surfaces', payload.surfaces.length >= 3],
    ['status carried', payload.freeTierCostStatus === 'cost-neutral'],
    ['measurement plan present', payload.measurementPlan.length === 3],
  ];
  let failed = 0;
  for (const [name, ok] of cases) {
    console.log(`  ${ok ? 'ok' : 'fail'} ${name}`);
    if (!ok) failed += 1;
  }
  console.log(`\nself-test: ${cases.length - failed} passed, ${failed} failed`);
  process.exit(failed ? 1 : 0);
}

let status = {};
try { status = JSON.parse(fs.readFileSync(path.join(ROOT, 'context', 'PROJECT_STATUS.json'), 'utf8')); } catch {}
const payload = buildBudget(status);
if (CHECK) {
  if (!fs.existsSync(OUT) || !fs.existsSync(DOC)) {
    console.error('build-intelligence-budget --check: missing outputs; run without --check');
    process.exit(1);
  }
  const current = JSON.parse(fs.readFileSync(OUT, 'utf8'));
  const comparableCurrent = { ...current, generatedAt: '' };
  const comparableNext = { ...payload, generatedAt: '' };
  if (JSON.stringify(comparableCurrent) !== JSON.stringify(comparableNext)) {
    console.error('build-intelligence-budget --check: artifact drift; run node scripts/build-intelligence-budget.mjs');
    process.exit(1);
  }
  console.log(`build-intelligence-budget --check: ok (${payload.surfaces.length} surface(s), ${(payload.totalBytes / 1024).toFixed(1)}KB)`);
  process.exit(0);
}
fs.writeFileSync(OUT, `${JSON.stringify(payload, null, 2)}\n`, 'utf8');
fs.writeFileSync(DOC, renderDoc(payload), 'utf8');
console.log(`build-intelligence-budget: ${payload.surfaces.length} surface(s), ${(payload.totalBytes / 1024).toFixed(1)}KB`);
